-- CAMERA-PROTOCOL-01: existing MySQL 8 database only; back up and review first.
-- DDL auto-commits. No table recreation, row mutation or automatic execution.
-- Preflight: verify the four existing constraints with SHOW CREATE TABLE.
-- Re-run only after checking which statements have already committed.
ALTER TABLE camera_source DROP CHECK ck_camera_source_type, ADD CONSTRAINT ck_camera_source_type CHECK(connection_category IN ('DEVICE','PLATFORM','RTSP','STREAM') AND (adapter_type IS NULL OR (CHAR_LENGTH(adapter_type) BETWEEN 1 AND 64 AND adapter_type NOT IN ('AUTO','SCAN'))) AND vendor_model_family IS NULL);
ALTER TABLE camera_source_credential DROP CHECK ck_camera_credential_purpose, ADD CONSTRAINT ck_camera_credential_purpose CHECK(purpose IN ('RTSP','STREAM','ONVIF','VENDOR_HTTP','PLATFORM_HTTP','DEVICE_HTTP'));
ALTER TABLE camera_source_endpoint DROP CHECK ck_camera_endpoint_protocol, ADD CONSTRAINT ck_camera_endpoint_protocol CHECK((purpose='STREAM' AND scheme IN ('rtsp','rtmp','http','https','gb28181') AND base_path='') OR (purpose='RTSP' AND scheme='rtsp' AND base_path='') OR (purpose='ONVIF' AND scheme IN ('http','https') AND base_path='/onvif/device_service') OR (purpose IN ('VENDOR_HTTP','DEVICE_HTTP') AND scheme IN ('http','https') AND base_path='') OR (purpose='PLATFORM_HTTP' AND scheme IN ('http','https') AND base_path LIKE '/%'));
ALTER TABLE camera_profile_locator DROP CHECK ck_camera_locator_kind, ADD CONSTRAINT ck_camera_locator_kind CHECK((locator_kind='RTSP' AND endpoint_purpose='RTSP' AND rtsp_transport IS NOT NULL AND rtsp_transport='TCP' AND rtsp_host_mode IS NOT NULL AND rtsp_secret_ciphertext IS NOT NULL AND rtsp_secret_nonce IS NOT NULL AND rtsp_secret_tag IS NOT NULL AND rtsp_encryption_key_id IS NOT NULL AND protocol_secret_ciphertext IS NULL AND protocol_secret_nonce IS NULL AND protocol_secret_tag IS NULL AND protocol_encryption_key_id IS NULL) OR (((locator_kind='ONVIF' AND endpoint_purpose IN ('ONVIF','DEVICE_HTTP')) OR (locator_kind IN ('HIKVISION','DAHUA') AND endpoint_purpose IN ('VENDOR_HTTP','DEVICE_HTTP')) OR (locator_kind='HIK_PLATFORM' AND endpoint_purpose='PLATFORM_HTTP') OR (locator_kind IN ('RTMP','FLV','HLS','CRTSP','GB28181') AND endpoint_purpose='STREAM')) AND rtsp_host_mode IS NULL AND rtsp_host IS NULL AND rtsp_port IS NULL AND rtsp_secret_ciphertext IS NULL AND rtsp_secret_nonce IS NULL AND rtsp_secret_tag IS NULL AND rtsp_encryption_key_id IS NULL AND rtsp_transport IS NULL AND protocol_secret_ciphertext IS NOT NULL AND protocol_secret_nonce IS NOT NULL AND protocol_secret_tag IS NOT NULL AND protocol_encryption_key_id IS NOT NULL));
